-- ###########################################################################
-- ## 004_reference_seed_data.sql
-- ###########################################################################

-- =============================================================================
-- MIGRATION 004: STATIC & REFERENCE SEED DATA ONLY
-- Project: Notre Dame College (NDC) Alumni Platform
-- Target: Supabase PostgreSQL
--
-- STRICT PRODUCTION DATA POLICY:
-- 1. Seeds ONLY structurally required batch_year keys (1 through 78) in
--    `public.batches` so foreign-key references on `alumni_profiles.batch_year`
--    succeed.
-- 2. Does NOT seed fabricated `estimated_total` formulas, invented
--    `representative_name` values, unverified `session` strings, or invented
--    historical labels; all unverified institutional fields are set to NULL.
-- 3. Reference placeholder rows in `public.official_notices` are explicitly
--    labeled `[REFERENCE PLACEHOLDER]` and set to `is_published = FALSE` so
--    they never appear as live published notices.
-- 4. Contains ZERO fake alumni profiles, ZERO demo accounts, ZERO fake posts,
--    ZERO fake comments/likes, ZERO fake verification requests, and ZERO fake
--    blood donors/requests.
-- =============================================================================

BEGIN;

SET search_path = public, extensions;

-- -----------------------------------------------------------------------------
-- 1. BATCH REFERENCE KEYS (Batches 1 to 78)
-- Only `batch_year` and `registered_count = 0` are populated; unverified
-- institutional fields remain NULL until entered by an administrator.
-- -----------------------------------------------------------------------------
-- -----------------------------------------------------------------------------
-- 1. BATCH REFERENCE KEYS (SZMC MBBS Batches 1 to 50)
-- Est. 1992 (Batch 1: Session 1991-92, Batch 35: Session 2025-26)
-- -----------------------------------------------------------------------------
INSERT INTO public.batches (
  batch_year,
  session,
  hsc_year,
  special_note,
  representative_name,
  representative_profile_id,
  registered_count,
  estimated_total
)
SELECT
  b.batch_num::SMALLINT AS batch_year,
  (1990 + b.batch_num)::TEXT || '-' || LPAD(((1990 + b.batch_num + 1) % 100)::TEXT, 2, '0') AS session,
  (1990 + b.batch_num)::SMALLINT AS hsc_year,
  CASE
    WHEN b.batch_num = 1 THEN 'Pioneer MBBS Batch (SZMC-01, Session 1991-92)'
    WHEN b.batch_num = 5 THEN '5th Batch (SZMC-05, Session 1995-96)'
    WHEN b.batch_num = 10 THEN '10th Milestone Batch (SZMC-10, Session 2000-01)'
    WHEN b.batch_num = 15 THEN '15th Batch (SZMC-15, Session 2005-06)'
    WHEN b.batch_num = 20 THEN '20th Batch (SZMC-20, Session 2010-11)'
    WHEN b.batch_num = 25 THEN 'Silver Jubilee Batch (SZMC-25, Session 2015-16)'
    WHEN b.batch_num = 30 THEN '30th Batch (SZMC-30, Session 2020-21)'
    WHEN b.batch_num = 35 THEN 'Current MBBS Session (SZMC-35, Session 2025-26)'
    ELSE 'MBBS Batch SZMC-' || LPAD(b.batch_num::TEXT, 2, '0')
  END AS special_note,
  'SZMC-' || LPAD(b.batch_num::TEXT, 2, '0') || ' Batch Coordinator' AS representative_name,
  NULL AS representative_profile_id,
  0 AS registered_count,
  CASE WHEN b.batch_num <= 10 THEN 100 WHEN b.batch_num <= 25 THEN 150 ELSE 200 END AS estimated_total
FROM generate_series(1, 50) AS b(batch_num)
ON CONFLICT (batch_year) DO UPDATE
SET
  session = EXCLUDED.session,
  hsc_year = EXCLUDED.hsc_year,
  special_note = COALESCE(public.batches.special_note, EXCLUDED.special_note),
  representative_name = COALESCE(public.batches.representative_name, EXCLUDED.representative_name),
  estimated_total = COALESCE(public.batches.estimated_total, EXCLUDED.estimated_total),
  updated_at = now();

-- -----------------------------------------------------------------------------
-- 1B. ACADEMIC STREAM & GROUP CONFIGURATION (`public.academic_stream_groups`)
-- Medical streams and departments for SZMC
-- -----------------------------------------------------------------------------
INSERT INTO public.academic_stream_groups (
  stream,
  group_code,
  expected_group_count,
  is_active
)
VALUES
  -- NOTE (fix): public.academic_stream_type only allows
  --   'Science', 'Humanities', 'Business Studies'.
  -- The previous 'MBBS' / medical-department rows raised
  --   invalid input value for enum academic_stream_type: "MBBS"
  -- which aborted this whole transaction, leaving public.batches EMPTY and
  -- breaking every alumni_profiles insert (FK on batch_year).
  ('Humanities', 'G', 4, TRUE),
  ('Humanities', 'H', 4, TRUE),
  ('Humanities', 'L', 4, TRUE),
  ('Humanities', 'W', 4, TRUE),
  ('Business Studies', 'A', 6, TRUE),
  ('Business Studies', 'B', 6, TRUE),
  ('Business Studies', 'C', 6, TRUE),
  ('Business Studies', 'D', 6, TRUE),
  ('Business Studies', 'E', 6, TRUE),
  ('Business Studies', 'F', 6, TRUE)
ON CONFLICT (stream, group_code) DO UPDATE
SET
  expected_group_count = EXCLUDED.expected_group_count,
  is_active = EXCLUDED.is_active,
  updated_at = now();

-- Stream-level metadata row (group_code IS NULL).
-- It is covered by the partial unique index uq_academic_stream_null_group_metadata,
-- which a (stream, group_code) conflict target does NOT match — so it needs its own
-- statement, otherwise re-running this migration raises a duplicate-key error.
INSERT INTO public.academic_stream_groups (stream, group_code, expected_group_count, is_active)
VALUES ('Science', NULL, 17, TRUE)
ON CONFLICT DO NOTHING;

-- -----------------------------------------------------------------------------
-- 2. OFFICIAL SZMC NOTICES
-- -----------------------------------------------------------------------------
INSERT INTO public.official_notices (
  ref_no,
  title,
  category,
  published_date,
  is_urgent,
  summary,
  full_content,
  pdf_url,
  file_size,
  signatory_name,
  signatory_designation,
  signatory_organization,
  is_published
)
VALUES
  (
    'SZMC/ALUMNI-2026/001',
    'Official Grand Reunion & Academic Conference 2026',
    'Reunion',
    CURRENT_DATE,
    TRUE,
    'Grand Reunion celebrating 35 MBBS Batches (1991–present) at SZMC Campus, Bogura.',
    E'Shaheed Ziaur Rahman Medical College (SZMC Bogura) Alumni Association warmly invites all registered alumni from Batch 01 to Batch 35 to the Grand Reunion and National Medical Conference.\n\nDate: December 2026\nVenue: SZMCH Auditorium & Main Campus Grounds, Bogura\n\nRegistration and peer verification can now be completed through the online portal.',
    NULL,
    NULL,
    'Dr. Tariqul Islam',
    'President, Alumni Association',
    'Shaheed Ziaur Rahman Medical College (SZMC Bogura)',
    TRUE
  ),
  (
    'SZMC/ALUMNI-2026/002',
    'Emergency Doctor Blood Network 24/7 Activation',
    'General',
    CURRENT_DATE,
    TRUE,
    'Active blood matching network connecting 35 MBBS batches across Bangladesh.',
    E'The SZMC Alumni Emergency Blood Network is active nationwide. Alumni physicians and medical officers are requested to verify their blood donor profile and availability status to support critical emergency blood matching.',
    NULL,
    NULL,
    'Dr. Kazi Rezwan',
    'Coordinator, Blood Network Committee',
    'Shaheed Ziaur Rahman Medical College (SZMC Bogura)',
    TRUE
  )
ON CONFLICT (ref_no) DO UPDATE
SET
  title = EXCLUDED.title,
  category = EXCLUDED.category,
  is_urgent = EXCLUDED.is_urgent,
  summary = EXCLUDED.summary,
  full_content = EXCLUDED.full_content,
  signatory_name = EXCLUDED.signatory_name,
  signatory_designation = EXCLUDED.signatory_designation,
  signatory_organization = EXCLUDED.signatory_organization,
  is_published = EXCLUDED.is_published,
  updated_at = now();

COMMIT;

-- ###########################################################################
-- ## 005_admin_phone_verification.sql
-- ###########################################################################

-- =============================================================================
-- MIGRATION 005: ADMIN-VERIFIED PHONE NUMBER LOGIN SUPPORT
-- Project: Notre Dame College (NDC) Alumni Platform
-- Target: Supabase PostgreSQL
-- =============================================================================

BEGIN;

-- 1. Add Phone Ownership Verification Columns to public.alumni_profiles
ALTER TABLE public.alumni_profiles
  ADD COLUMN IF NOT EXISTS phone_ownership_verified BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS phone_verified_at TIMESTAMPTZ NULL,
  ADD COLUMN IF NOT EXISTS phone_verified_by_profile_id BIGINT NULL REFERENCES public.alumni_profiles(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS phone_verification_notes TEXT NULL;

-- 2. Partial Unique Index on Verified Phone Numbers
-- Ensures two active verified alumni accounts cannot claim the exact same verified mobile number
CREATE UNIQUE INDEX IF NOT EXISTS uq_alumni_verified_phone
  ON public.alumni_profiles (phone)
  WHERE phone_ownership_verified = TRUE AND phone IS NOT NULL;

-- 3. Index for Admin Verification Queue queries
CREATE INDEX IF NOT EXISTS idx_alumni_phone_verification_queue
  ON public.alumni_profiles (phone_ownership_verified, batch_year)
  WHERE phone IS NOT NULL;

-- 4. Audit Log Comment
COMMENT ON COLUMN public.alumni_profiles.phone_ownership_verified IS 'Indicates whether an administrator has independently verified ownership of this phone number to permit Phone + Password login.';
COMMENT ON COLUMN public.alumni_profiles.phone_verified_at IS 'Timestamp when administrator approved phone ownership verification.';
COMMENT ON COLUMN public.alumni_profiles.phone_verified_by_profile_id IS 'Admin profile ID who validated phone ownership.';
COMMENT ON COLUMN public.alumni_profiles.phone_verification_notes IS 'Audit notes regarding the phone verification method (e.g. phone call, batch representative confirmation).';

COMMIT;

-- ###########################################################################
-- ## 006_edge_functions_support.sql
-- ###########################################################################

-- =============================================================================
-- MIGRATION 006: DISTRIBUTED RATE LIMITING & EDGE FUNCTIONS SUPPORT
-- Project: Notre Dame College (NDC) Alumni Platform
-- Target: Supabase PostgreSQL (Free Tier compatible, Zero External Services)
-- Description: Creates atomic distributed rate limiting table and function.
--              Strictly restricted to trusted server-side execution (service_role).
-- =============================================================================

BEGIN;

-- 1. Distributed Rate Limiter Table
-- Replaces ephemeral in-memory rate limiting across multi-region Supabase Edge Functions
CREATE TABLE IF NOT EXISTS public.auth_rate_limits (
  key TEXT PRIMARY KEY,
  attempts INTEGER NOT NULL DEFAULT 1,
  reset_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Index on reset_at for fast expiration cleanup
CREATE INDEX IF NOT EXISTS idx_auth_rate_limits_reset ON public.auth_rate_limits (reset_at);

-- Enable RLS and revoke client access
ALTER TABLE public.auth_rate_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.auth_rate_limits FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public.auth_rate_limits TO service_role;

-- 2. Atomic Rate-Limiting Function (SECURITY DEFINER)
-- Atomically checks and increments attempts within a sliding time window.
-- Uses clock_timestamp() for real-time concurrency across transactions.
-- Returns TRUE if request is within limits, FALSE if rate limit exceeded.
DROP FUNCTION IF EXISTS public.check_and_increment_rate_limit(TEXT, INTEGER, INTEGER) CASCADE;
CREATE OR REPLACE FUNCTION public.check_and_increment_rate_limit(
  p_key TEXT,
  p_max_attempts INTEGER,
  p_window_seconds INTEGER
) RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_now TIMESTAMPTZ := clock_timestamp();
  v_attempts INTEGER;
  v_reset_at TIMESTAMPTZ;
BEGIN
  -- Housekeeping: delete expired entry for this key if it passed reset_at
  DELETE FROM public.auth_rate_limits WHERE key = p_key AND reset_at <= v_now;

  -- Upsert: insert initial attempt or increment existing valid window
  INSERT INTO public.auth_rate_limits (key, attempts, reset_at)
  VALUES (p_key, 1, v_now + (p_window_seconds || ' seconds')::INTERVAL)
  ON CONFLICT (key) DO UPDATE
  SET attempts = CASE 
    WHEN public.auth_rate_limits.reset_at <= clock_timestamp() THEN 1 
    ELSE public.auth_rate_limits.attempts + 1 
  END,
  reset_at = CASE
    WHEN public.auth_rate_limits.reset_at <= clock_timestamp() THEN clock_timestamp() + (p_window_seconds || ' seconds')::INTERVAL
    ELSE public.auth_rate_limits.reset_at
  END
  RETURNING attempts, reset_at INTO v_attempts, v_reset_at;

  IF v_attempts > p_max_attempts THEN
    RETURN FALSE; -- Block: Rate limit exceeded
  END IF;

  RETURN TRUE; -- Allow: Within quota
END;
$$;

-- Explicitly revoke from public, anon, and authenticated so clients cannot call this RPC
REVOKE ALL ON FUNCTION public.check_and_increment_rate_limit(TEXT, INTEGER, INTEGER) FROM PUBLIC, anon, authenticated;

-- Allow ONLY the trusted server-side role (used by Edge Functions) to execute
GRANT EXECUTE ON FUNCTION public.check_and_increment_rate_limit(TEXT, INTEGER, INTEGER) TO service_role;

-- Comments for database documentation
COMMENT ON TABLE public.auth_rate_limits IS 'Stores distributed sliding-window rate limit counters for Edge Functions across global instances.';
COMMENT ON FUNCTION public.check_and_increment_rate_limit IS 'Atomic distributed rate limiter for phone login, admin actions, and public crawlers. Callable only via service_role.';

COMMIT;

-- ###########################################################################
-- ## 007_phone_login_additive_support.sql
-- ###########################################################################

-- =============================================================================
-- MIGRATION 007: SAFE ADDITIVE PHONE LOGIN & UNIQUENESS SUPPORT
-- Project: Notre Dame College (NDC) Alumni Platform
-- Target: Supabase PostgreSQL
-- Description:
--   1. Adds SECURITY DEFINER helper public.check_phone_available() to allow
--      safe pre-registration availability checks without exposing private phone numbers.
--   2. Adds lookup index on phone column for high-speed edge function queries.
--   3. Does NOT modify or delete any existing user accounts or database records.
--   4. Preserves all existing RLS policies and table structures.
-- =============================================================================

BEGIN;

-- 1. High-speed lookup index for Edge Function phone queries
CREATE INDEX IF NOT EXISTS idx_alumni_profiles_phone_lookup
  ON public.alumni_profiles (phone)
  WHERE phone IS NOT NULL;

-- 2. SECURITY DEFINER function to check if a phone number is available for registration
-- Returns TRUE if available (not registered by another user), FALSE if already claimed.
DROP FUNCTION IF EXISTS public.check_phone_available(TEXT) CASCADE;
CREATE OR REPLACE FUNCTION public.check_phone_available(p_phone TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_clean TEXT;
  v_exists BOOLEAN;
BEGIN
  IF p_phone IS NULL OR trim(p_phone) = '' THEN
    RETURN TRUE;
  END IF;

  v_clean := trim(p_phone);

  SELECT EXISTS (
    SELECT 1
    FROM public.alumni_profiles
    WHERE phone = v_clean
       OR phone = replace(v_clean, '+', '')
       OR ('+' || phone) = v_clean
  ) INTO v_exists;

  RETURN NOT v_exists;
END;
$$;

-- Grant execution to anon and authenticated callers
GRANT EXECUTE ON FUNCTION public.check_phone_available(TEXT) TO anon, authenticated, service_role;

COMMENT ON FUNCTION public.check_phone_available(TEXT) IS
  'Checks if a phone number is available during registration without exposing registered alumni phone numbers.';

COMMIT;

